        // part of the sealed trait so that no trait is publicly implemented by `OwnedSortedLinkedListStorage` besides `Storage`
        fn borrow(&self) -> &[Node<T, Idx>];
        fn borrow_mut(&mut self) -> &mut [Node<T, Idx>];
