            Idx: LenType,
        {
            this
        }
    }
    impl<T, Idx, const N: usize> SortedLinkedListStorage<T, Idx>
        for OwnedSortedLinkedListStorage<T, Idx, N>
    {
    }

    impl<T, Idx> SortedLinkedListSealedStorage<T, Idx> for ViewSortedLinkedListStorage<T, Idx> {
