    ///
    ///     // Interrupt occurs.
    /// #   interrupt();
    ///
    ///     consumer.dequeue().unwrap();
    /// }
    /// ```
    pub fn split(&mut self) -> (Producer<'_, T>, Consumer<'_, T>) {
        (
            Producer { rb: self.as_view() },
            Consumer { rb: self.as_view() },
        )
    }
}

