    /// first subsequent dequeue will succeed.
    #[inline]
    pub fn ready(&self) -> bool {
        !self.rb.is_empty()
    }

    /// Returns the number of elements in the queue.
    #[inline]
    pub fn len(&self) -> usize {
        self.rb.len()
    }

    /// Returns whether the queue is empty.
